function ground(c,camera){c.save();c.globalCompositeOperation='screen';for(const l of lights){const progress=1-l.life/l.max,r=l.r*(.75+progress*.3);c.save();c.translate(l.x-camera,l.y);c.scale(1,.32);c.globalAlpha=l.life/l.max*.23;const glow=c.createRadialGradient(0,0,0,0,0,r);glow.addColorStop(0,l.color);glow.addColorStop(.45,l.color+'55');glow.addColorStop(1,l.color+'00');c.fillStyle=glow;c.fillRect(-r,-r,r*2,r*2);c.restore();}c.restore();}
