function projectile(c,q,x,y,time){if(root.DungeonArt?.projectile(c,q,x,y,time))return;c.save();c.translate(x,y-(q.team==='enemy'?135:q.kind==='bullet'?155:125));c.rotate(Math.atan2(q.vy,q.vx));const enemy=q.team==='enemy',orb=q.kind!=='bullet',r=enemy?17:orb?19:9;c.globalCompositeOperation='lighter';const glow=c.createRadialGradient(0,0,0,0,0,r*1.8);glow.addColorStop(0,'#fff7ed');glow.addColorStop(.3,q.color);glow.addColorStop(1,'#ffffff00');c.fillStyle=glow;c.fillRect(-r*1.8,-r*1.8,r*3.6,r*3.6);const trail=enemy?30:orb?42:60,g=c.createLinearGradient(-trail,0,0,0);g.addColorStop(0,'#ffffff00');g.addColorStop(1,q.color);c.fillStyle=g;c.beginPath();c.moveTo(-trail,-2);c.lineTo(0,-r*.45);c.lineTo(8,0);c.lineTo(0,r*.45);c.lineTo(-trail,2);c.closePath();c.fill();if(orb){c.strokeStyle=enemy?'#ffd0ff':'#eee0ff';c.lineWidth=2;c.beginPath();c.arc(0,0,r*.65,time*3,time*3+Math.PI*1.6);c.stroke();}else shard(c,0,0,10,'#fff3ff',Math.PI/2);c.restore();}
